	e.ServeHTTP(rec, req)
	status := rec.Code
	flag := ""
	if status != 404 {
		flag = "  <<< NOT 404"
	}
	fmt.Printf("ok     %-28s %-6s %-20s -> %d%s\n", name, method, path, status, flag)
}

func main() {
	paths := []string{"/", "//", "///", "/a/b/c", "/a/", "/a//b", "/x", "/a/b/c/", "/a/b/c/d/e", "/:foo", "/*", "/a/:b/c", "/%2F", "/a/b/c?x=1", "/static/../a", "/a/b/", "/a/b/c/d", "/A/B/C", "/a/b/c\x00"}
