	e.POST("/a/:id/c", func(c echo.Context) error { return c.String(200, "param") })
	e.GET("/static/*", func(c echo.Context) error { return c.String(200, "any") })
	e.GET("/users/:id", func(c echo.Context) error { return c.String(200, "user") })
	e.GET("/users/:id/files/:fid", func(c echo.Context) error { return c.String(200, "file") })
	e.Any("/any", func(c echo.Context) error { return c.String(200, "any2") })

	for _, m := range methods {
		for _, p := range paths {
			check("routes", e, m, p)
		}
	}

	// minimal routers
	e2 := echo.New()
	e2.GET("/", func(c echo.Context) error { return c.String(200, "root") })
	for _, m := range methods {
		for _, p := range paths {
			check("only-root", e2, m, p)
		}
	}

	e3 := echo.New()
	e3.GET("/a/:b", func(c echo.Context) error { return c.String(200, "ab") })
	for _, m := range methods {
		for _, p := range paths {
			check("param-only", e3, m, p)
		}
	}

	e4 := echo.New()
	for _, m := range methods {
		for _, p := range paths {
			check("empty-router", e4, m, p)
		}
	}

	// direct Find calls
	e5 := echo.New()
	e5.GET("/a/b", func(c echo.Context) error { return c.String(200, "ab") })
	for _, p := range paths {
