package main

import (
	"fmt"
	"math/rand"
	"net/http"
	"net/http/httptest"
	"strings"
	"time"

	"github.com/labstack/echo/v4"
)

type result struct {
	panicVal interface{}
	handler  string
	path     string
	timedOut bool
}

func tryFind(e *echo.Echo, method, path string) (res result) {
	done := make(chan result, 1)
	go func() {
		defer func() {
			if r := recover(); r != nil {
				done <- result{panicVal: r}
			}
		}()
		c := e.NewContext(httptest.NewRequest(http.MethodGet, "/", nil), httptest.NewRecorder())
		e.Router().Find(method, path, c)
		h := c.Handler()
		name := "nil"
		if h != nil {
			name = "handler"
		}
		done <- result{handler: name, path: c.Path()}
	}()
	select {
	case r := <-done:
		return r
	case <-time.After(2 * time.Second):
		return result{timedOut: true}
	}
}

var segs = []string{"a", "b", "c", ":x", "*"}

func randPath(rnd *rand.Rand) string {
	n := rnd.Intn(4)
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, segs[rnd.Intn(len(segs))])
	}
	p := "/" + strings.Join(parts, "/")
	if rnd.Intn(4) == 0 {
		p += "/"
	}
	return p
}

var reqPaths = []string{"/", "//", "///", "/a", "/a/", "/a/b", "/a/b/", "/a/b/c", "/a/b/c/d", "/b", "/b/a", "/c/b/a", "/a//b", "/a/b//", "/x", "/x/y", "/a/b/c/", "/a/b/c/d/e", "/ab", "/abc", "/a/bc", "/:x", "/*", "/a/:x", "/a/*", "/a/b/:x", "/a/b/*", "/A", "/a/B", ""}

var methods = []string{"GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS", "HEAD", "TRACE", "CONNECT", "PROPFIND", "REPORT", "FOO", ""}

func main() {
	rnd := rand.New(rand.NewSource(42))
	panics, hangs, nils := 0, 0, 0
	for iter := 0; iter < 20000; iter++ {
		e := echo.New()
		nRoutes := rnd.Intn(6)
		registered := []string{}
		for i := 0; i < nRoutes; i++ {
			p := randPath(rnd)
			if p == "" {
				continue
			}
			registered = append(registered, p)
			func() {
				defer func() { recover() }()
				e.GET(p, func(c echo.Context) error { return c.String(200, "ok") })
			}()
		}
		for _, p := range reqPaths {
			for _, m := range methods {
				r := tryFind(e, m, p)
				if r.panicVal != nil {
					panics++
					if panics < 15 {
						fmt.Printf("PANIC routes=%q method=%q path=%q -> %v\n", registered, m, p, r.panicVal)
					}
				}
				if r.timedOut {
					hangs++
					if hangs < 15 {
						fmt.Printf("HANG  routes=%q method=%q path=%q\n", registered, m, p)
					}
				}
				if r.handler == "nil" {
					nils++
					if nils < 15 {
						fmt.Printf("NILH  routes=%q method=%q path=%q\n", registered, m, p)
					}
				}
			}
		}
	}
	fmt.Printf("done: panics=%d hangs=%d nilhandlers=%d\n", panics, hangs, nils)
}
EOF
